class Solution:
    def findLUSlength(self, strs: List[str]) -> int:
        def isSub(s, t):
            it = iter(t)
            return all(c in it for c in s)
        ans = -1
        for i, s in enumerate(strs):
            if all(not isSub(s, t) for j, t in enumerate(strs) if i != j):
                ans = max(ans, len(s))
        return ans

