class Solution {
public:
    bool isSub(const string& s, const string& t) {
        int i = 0;
        for (char c : t) if (i < s.size() && c == s[i]) i++;
        return i == s.size();
    }
    int findLUSlength(vector<string>& strs) {
        int ans = -1;
        for (int i = 0; i < strs.size(); i++) {
            bool ok = true;
            for (int j = 0; j < strs.size() && ok; j++)
                if (i != j && isSub(strs[i], strs[j])) ok = false;
            if (ok) ans = max(ans, (int)strs[i].size());
        }
        return ans;
    }
};

